-- Separate factual Source use from reproduction of third-party material.

create table tongs.reference_visual_source_use_revisions(
 id uuid primary key default gen_random_uuid(),use_id uuid not null,workspace_id uuid not null,workpiece_id uuid not null,opportunity_id uuid not null,revision bigint not null check(revision>0),previous_revision_id uuid,previous_revision bigint,
 opportunity_revision_id uuid not null references tongs.reference_visual_opportunity_revisions(id),source_revision_id uuid not null references tongs.source_revisions(id),workpiece_source_link_revision_id uuid not null references tongs.workpiece_source_link_revisions(id),
 use_classification text not null check(use_classification in('facts_data_only','quoted_or_excerpted_text','third_party_media','mixed')),creator_confirmed boolean not null,confirmation_note text,provenance_json jsonb not null default '{}'::jsonb check(jsonb_typeof(provenance_json)='object'),
 content_hash text not null check(content_hash~'^[0-9a-f]{64}$'),immutable_revision_hash text not null check(immutable_revision_hash~'^[0-9a-f]{64}$'),created_by uuid not null,created_at timestamptz not null default now(),
 unique(id,workspace_id,workpiece_id,use_id,revision),unique(workspace_id,workpiece_id,use_id,revision),foreign key(previous_revision_id,workspace_id,workpiece_id,use_id,previous_revision) references tongs.reference_visual_source_use_revisions(id,workspace_id,workpiece_id,use_id,revision)
);
create table tongs.reference_visual_source_use_sequences(workspace_id uuid not null,workpiece_id uuid not null,opportunity_id uuid not null,use_id uuid not null,current_use_revision_id uuid not null,current_use_revision bigint not null,updated_at timestamptz not null default now(),primary key(workspace_id,workpiece_id,opportunity_id),foreign key(current_use_revision_id,workspace_id,workpiece_id,use_id,current_use_revision) references tongs.reference_visual_source_use_revisions(id,workspace_id,workpiece_id,use_id,revision));

alter table tongs.reference_visual_candidate_revisions add column source_use_revision_id uuid references tongs.reference_visual_source_use_revisions(id),alter column rights_declaration_revision_id drop not null;
alter table tongs.reference_visual_render_operations add column source_use_revision_id uuid references tongs.reference_visual_source_use_revisions(id),alter column rights_declaration_revision_id drop not null;
alter table tongs.reference_visual_operation_receipts drop constraint reference_visual_operation_receipts_operation_type_check;
alter table tongs.reference_visual_operation_receipts add constraint reference_visual_operation_receipts_operation_type_check check(operation_type in('plan_commit','source_fulfillment','evidence_commit','recipe_commit','rights_commit','source_use_commit','asset_restriction','sequence_commit','selection','creator_amendment'));

create or replace function tongs.commit_reference_visual_source_use(p_workspace_id uuid,p_workpiece_id uuid,p_opportunity_id uuid,p_use_id uuid,p_expected_revision bigint,p_expected_opportunity_revision_id uuid,p_source_revision_id uuid,p_workpiece_source_link_revision_id uuid,p_use_classification text,p_creator_confirmed boolean,p_confirmation_note text,p_provenance_json jsonb,p_operation_id text,p_operation_fingerprint text,p_actor_id uuid)returns jsonb language plpgsql security definer set search_path=pg_catalog,tongs as $$
declare op tongs.reference_visual_operation_receipts%rowtype;seq tongs.reference_visual_source_use_sequences%rowtype;prev tongs.reference_visual_source_use_revisions%rowtype;opp tongs.reference_visual_opportunity_revisions%rowtype;r tongs.reference_visual_source_use_revisions%rowtype;n bigint;h text;ih text;result jsonb;
begin
 if not tongs.has_workspace_role(p_workspace_id,'editor')or auth.uid() is distinct from p_actor_id then raise exception 'workspace editor authority required' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_operation_id,0));select * into op from tongs.reference_visual_operation_receipts where operation_id=p_operation_id;
 if found then if op.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict');end if;return op.receipt_json;end if;
 select rv.* into opp from tongs.reference_visual_plan_sequences ps join tongs.reference_visual_plan_membership m on m.plan_revision_id=ps.current_plan_revision_id join tongs.reference_visual_opportunity_revisions rv on rv.id=m.opportunity_revision_id where ps.workspace_id=p_workspace_id and ps.workpiece_id=p_workpiece_id and m.opportunity_id=p_opportunity_id for update of rv;
 if not found or opp.id is distinct from p_expected_opportunity_revision_id then return jsonb_build_object('disposition','opportunity_revision_conflict');end if;
 if opp.source_status<>'linked' or opp.source_revision_id is distinct from p_source_revision_id or opp.workpiece_source_link_revision_id is distinct from p_workpiece_source_link_revision_id then return jsonb_build_object('disposition','linked_source_revision_required');end if;
 if p_use_classification='facts_data_only' and opp.visual_subtype not in('chart','timeline','stat_card','comparison') then return jsonb_build_object('disposition','source_use_incompatible_with_treatment');end if;
 if opp.visual_subtype in('document_excerpt','quote_card') and p_use_classification not in('quoted_or_excerpted_text','mixed') then return jsonb_build_object('disposition','source_use_incompatible_with_treatment');end if;
 if opp.visual_subtype in('archival_still','archival_sequence') and p_use_classification not in('third_party_media','mixed') then return jsonb_build_object('disposition','source_use_incompatible_with_treatment');end if;
 select * into seq from tongs.reference_visual_source_use_sequences where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and opportunity_id=p_opportunity_id for update;
 if coalesce(seq.current_use_revision,0)<>p_expected_revision then return jsonb_build_object('disposition','source_use_revision_conflict','current_revision',coalesce(seq.current_use_revision,0));end if;
 if p_expected_revision>0 then select * into prev from tongs.reference_visual_source_use_revisions where id=seq.current_use_revision_id;end if;n:=p_expected_revision+1;
 h:=encode(extensions.digest(convert_to(jsonb_build_object('opportunity_revision_id',opp.id,'source_revision_id',p_source_revision_id,'workpiece_source_link_revision_id',p_workpiece_source_link_revision_id,'use_classification',p_use_classification,'creator_confirmed',p_creator_confirmed,'confirmation_note',p_confirmation_note,'provenance',coalesce(p_provenance_json,'{}'))::text,'UTF8'),'sha256'),'hex');ih:=encode(extensions.digest(convert_to(jsonb_build_object('use_id',p_use_id,'revision',n,'previous_revision_id',prev.id,'content_hash',h)::text,'UTF8'),'sha256'),'hex');
 insert into tongs.reference_visual_source_use_revisions(use_id,workspace_id,workpiece_id,opportunity_id,revision,previous_revision_id,previous_revision,opportunity_revision_id,source_revision_id,workpiece_source_link_revision_id,use_classification,creator_confirmed,confirmation_note,provenance_json,content_hash,immutable_revision_hash,created_by)values(p_use_id,p_workspace_id,p_workpiece_id,p_opportunity_id,n,prev.id,prev.revision,opp.id,p_source_revision_id,p_workpiece_source_link_revision_id,p_use_classification,p_creator_confirmed,p_confirmation_note,coalesce(p_provenance_json,'{}'),h,ih,p_actor_id)returning * into r;
 insert into tongs.reference_visual_source_use_sequences values(p_workspace_id,p_workpiece_id,p_opportunity_id,p_use_id,r.id,r.revision,now())on conflict(workspace_id,workpiece_id,opportunity_id)do update set use_id=excluded.use_id,current_use_revision_id=excluded.current_use_revision_id,current_use_revision=excluded.current_use_revision,updated_at=now();
 result:=jsonb_build_object('disposition','committed','source_use_revision',to_jsonb(r));insert into tongs.reference_visual_operation_receipts values(p_operation_id,p_operation_fingerprint,'source_use_commit',p_workspace_id,p_workpiece_id,'committed',r.id,result,p_actor_id,now());return result;
end$$;

create or replace function tongs.begin_reference_visual_render_v2(p_workspace_id uuid,p_workpiece_id uuid,p_opportunity_revision_id uuid,p_recipe_revision_id uuid,p_source_use_revision_id uuid,p_rights_declaration_revision_id uuid,p_renderer_name text,p_renderer_version text,p_operation_id text,p_operation_fingerprint text,p_actor_id uuid)returns jsonb language plpgsql security definer set search_path=pg_catalog,tongs as $$
declare op tongs.reference_visual_render_operations%rowtype;use_rev tongs.reference_visual_source_use_revisions%rowtype;
begin
 if not tongs.has_workspace_role(p_workspace_id,'editor')or auth.uid() is distinct from p_actor_id then raise exception 'workspace editor authority required' using errcode='42501';end if;perform pg_advisory_xact_lock(hashtextextended(p_operation_id,0));select * into op from tongs.reference_visual_render_operations where operation_id=p_operation_id;if found then if op.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict');end if;return jsonb_build_object('disposition','replay','operation',to_jsonb(op));end if;
 if not exists(select 1 from tongs.reference_visual_recipe_sequences s join tongs.reference_visual_recipe_revisions r on r.id=s.current_recipe_revision_id where r.id=p_recipe_revision_id and r.workspace_id=p_workspace_id and r.workpiece_id=p_workpiece_id and not exists(select 1 from unnest(r.evidence_revision_ids)e(id) join tongs.reference_visual_evidence_revisions ev on ev.id=e.id where ev.confirmation_state<>'creator_confirmed'))then return jsonb_build_object('disposition','current_confirmed_recipe_required');end if;
 select su.* into use_rev from tongs.reference_visual_source_use_sequences s join tongs.reference_visual_source_use_revisions su on su.id=s.current_use_revision_id where s.workspace_id=p_workspace_id and s.workpiece_id=p_workpiece_id and su.id=p_source_use_revision_id and su.opportunity_revision_id=p_opportunity_revision_id and su.creator_confirmed;
 if not found then return jsonb_build_object('disposition','current_confirmed_source_use_required');end if;
 if use_rev.use_classification='facts_data_only' then if p_rights_declaration_revision_id is not null then return jsonb_build_object('disposition','rights_not_applicable');end if;elsif not exists(select 1 from tongs.reference_visual_rights_declaration_sequences s where s.workspace_id=p_workspace_id and s.workpiece_id=p_workpiece_id and s.current_declaration_revision_id=p_rights_declaration_revision_id)then return jsonb_build_object('disposition','current_rights_declaration_required');end if;
 insert into tongs.reference_visual_render_operations(operation_id,operation_fingerprint,workspace_id,workpiece_id,opportunity_revision_id,recipe_revision_id,source_use_revision_id,rights_declaration_revision_id,renderer_name,renderer_version,created_by)values(p_operation_id,p_operation_fingerprint,p_workspace_id,p_workpiece_id,p_opportunity_revision_id,p_recipe_revision_id,p_source_use_revision_id,p_rights_declaration_revision_id,p_renderer_name,p_renderer_version,p_actor_id)returning * into op;return jsonb_build_object('disposition','reserved','operation',to_jsonb(op));
end$$;

create or replace function tongs.commit_reference_visual_render(p_operation_id text,p_operation_fingerprint text,p_path text,p_mime_type text,p_byte_size bigint,p_content_hash text,p_storage_bucket text,p_storage_key text,p_width integer,p_height integer,p_render_evidence jsonb)returns jsonb language plpgsql security definer set search_path=pg_catalog,tongs as $$
declare op tongs.reference_visual_render_operations%rowtype;a tongs.assets%rowtype;c tongs.reference_visual_candidates%rowtype;r tongs.reference_visual_candidate_revisions%rowtype;recipe tongs.reference_visual_recipe_revisions%rowtype;h text;ih text;receipt jsonb;
begin
 if auth.role()<>'service_role'then raise exception 'Reference Visual render commit requires service authority'using errcode='42501';end if;select * into op from tongs.reference_visual_render_operations where operation_id=p_operation_id for update;if not found then return jsonb_build_object('disposition','operation_not_found');end if;if op.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict');end if;if op.state='candidate_committed'then return op.receipt_json;end if;if p_mime_type not in('image/png','image/svg+xml')or p_byte_size<=0 or p_content_hash!~'^[0-9a-f]{64}$'or p_width<=0 or p_height<=0 then return jsonb_build_object('disposition','invalid_verified_render_evidence');end if;
 select * into recipe from tongs.reference_visual_recipe_revisions where id=op.recipe_revision_id;select * into a from tongs.assets where workspace_id=op.workspace_id and workpiece_id=op.workpiece_id and operation_id=p_operation_id and asset_kind='reference_visual_image'for update;if found then if a.content_hash<>p_content_hash or a.storage_bucket<>p_storage_bucket or a.storage_key<>p_storage_key or a.bytes<>p_byte_size then return jsonb_build_object('disposition','asset_replay_conflict');end if;else insert into tongs.assets(workspace_id,workpiece_id,path,mime_type,bytes,storage_bucket,storage_key,provider,provider_request_id,request_id,created_by,asset_kind,status,metadata_json,width,height,operation_id,operation_fingerprint,content_hash,ready_at)values(op.workspace_id,op.workpiece_id,p_path,p_mime_type,p_byte_size,p_storage_bucket,p_storage_key,op.renderer_name,p_operation_id,p_operation_id,op.created_by,'reference_visual_image','ready',jsonb_build_object('renderer_name',op.renderer_name,'renderer_version',op.renderer_version,'recipe_revision_id',op.recipe_revision_id,'source_use_revision_id',op.source_use_revision_id),p_width,p_height,p_operation_id,p_operation_fingerprint,p_content_hash,now())returning * into a;end if;
 insert into tongs.reference_visual_candidates(workspace_id,workpiece_id,opportunity_id,created_by)select op.workspace_id,op.workpiece_id,o.opportunity_id,op.created_by from tongs.reference_visual_opportunity_revisions o where o.id=op.opportunity_revision_id returning * into c;h:=encode(extensions.digest(convert_to(jsonb_build_object('asset_hash',a.content_hash,'opportunity_revision_id',op.opportunity_revision_id,'recipe_revision_id',recipe.id,'source_use_revision_id',op.source_use_revision_id,'rights_revision_id',op.rights_declaration_revision_id,'renderer',op.renderer_name,'renderer_version',op.renderer_version,'render_evidence',p_render_evidence)::text,'UTF8'),'sha256'),'hex');ih:=encode(extensions.digest(convert_to(jsonb_build_object('candidate_id',c.id,'revision',1,'content_hash',h,'operation_id',p_operation_id)::text,'UTF8'),'sha256'),'hex');
 insert into tongs.reference_visual_candidate_revisions(candidate_id,workspace_id,workpiece_id,opportunity_id,revision,opportunity_revision_id,opportunity_revision,recipe_revision_id,recipe_revision,candidate_kind,asset_id,source_use_revision_id,rights_declaration_revision_id,renderer_name,renderer_version,canonical_render_hash,render_receipt_json,provenance_json,content_hash,immutable_revision_hash,created_by)select c.id,op.workspace_id,op.workpiece_id,o.opportunity_id,1,o.id,o.revision,recipe.id,recipe.revision,'rendered_visual',a.id,op.source_use_revision_id,op.rights_declaration_revision_id,op.renderer_name,op.renderer_version,p_content_hash,p_render_evidence,jsonb_build_object('authority','tongs-render-v2','source_use_revision_id',op.source_use_revision_id),h,ih,op.created_by from tongs.reference_visual_opportunity_revisions o where o.id=op.opportunity_revision_id returning * into r;
 receipt:=jsonb_build_object('disposition','committed','operation_id',p_operation_id,'opportunity_revision_id',op.opportunity_revision_id,'recipe_revision_id',recipe.id,'source_use_revision_id',op.source_use_revision_id,'rights_declaration_revision_id',op.rights_declaration_revision_id,'renderer_name',op.renderer_name,'renderer_version',op.renderer_version,'asset',to_jsonb(a),'candidate_revision',to_jsonb(r));update tongs.reference_visual_render_operations set state='candidate_committed',render_evidence_json=p_render_evidence,output_asset_id=a.id,result_candidate_revision_id=r.id,failed_stage=null,failure_code=null,failure_message=null,receipt_json=receipt,updated_at=now()where operation_id=p_operation_id;return receipt;
end$$;

create or replace function tongs.reference_visual_candidate_assets_available(p_candidate_revision_id uuid)returns boolean language sql stable security definer set search_path=pg_catalog,tongs as $$
 select not exists(select 1 from tongs.reference_visual_candidate_revisions c join lateral(select c.asset_id as asset_id where c.asset_id is not null union all select sm.asset_id from tongs.reference_visual_sequence_membership sm where sm.sequence_revision_id=c.sequence_revision_id)member on true join tongs.reference_visual_asset_restriction_sequences rs on rs.asset_id=member.asset_id join tongs.reference_visual_asset_restriction_revisions rr on rr.id=rs.current_restriction_revision_id where c.id=p_candidate_revision_id and rr.availability_state in('disputed','disabled'))
$$;
create or replace function tongs.reject_restricted_reference_visual_selection()returns trigger language plpgsql set search_path=pg_catalog,tongs as $$begin if not tongs.reference_visual_candidate_assets_available(new.candidate_revision_id)then raise exception 'asset_restricted'using errcode='23514';end if;return new;end$$;
drop trigger if exists reference_visual_selection_assets_available on tongs.reference_visual_selections;create trigger reference_visual_selection_assets_available before insert on tongs.reference_visual_selections for each row execute function tongs.reject_restricted_reference_visual_selection();

create or replace function tongs.reference_visual_candidate_release_ready(p_candidate_revision_id uuid)returns boolean language sql stable security definer set search_path=pg_catalog,tongs as $$
 select coalesce((select tongs.reference_visual_candidate_assets_available(c.id) and case when u.use_classification='facts_data_only' then u.creator_confirmed and c.rights_declaration_revision_id is null else rd.rights_status is not null and rd.rights_status<>'rights_unresolved'end from tongs.reference_visual_candidate_revisions c left join tongs.reference_visual_source_use_revisions u on u.id=c.source_use_revision_id left join tongs.reference_visual_rights_declaration_revisions rd on rd.id=c.rights_declaration_revision_id where c.id=p_candidate_revision_id),false)
$$;
create or replace function tongs.reject_unready_reference_visual_selection()returns trigger language plpgsql set search_path=pg_catalog,tongs as $$begin if not tongs.reference_visual_candidate_release_ready(new.candidate_revision_id)then raise exception 'candidate_not_release_ready'using errcode='23514';end if;return new;end$$;
create trigger reference_visual_selection_release_ready before insert on tongs.reference_visual_selections for each row execute function tongs.reject_unready_reference_visual_selection();

create or replace function tongs.read_current_reference_visual_plan(p_workspace_id uuid,p_workpiece_id uuid)returns jsonb language sql stable security definer set search_path=pg_catalog,tongs as $$
 select case when not tongs.has_workspace_role(p_workspace_id,'viewer')then null else jsonb_build_object('plan_revision',to_jsonb(p),'opportunities',coalesce((select jsonb_agg(jsonb_build_object('membership',to_jsonb(m),'opportunity_revision',to_jsonb(o),'source_revision',to_jsonb(sr),'source_link_revision',to_jsonb(sl),'evidence',coalesce((select jsonb_agg(to_jsonb(e)order by e.created_at)from tongs.reference_visual_evidence_sequences es join tongs.reference_visual_evidence_revisions e on e.id=es.current_evidence_revision_id where es.workspace_id=m.workspace_id and es.workpiece_id=m.workpiece_id and e.opportunity_id=m.opportunity_id),'[]'::jsonb),'source_use',to_jsonb(su),'recipe',to_jsonb(rr),'rights_declaration',to_jsonb(rd),'candidates',coalesce((select jsonb_agg(to_jsonb(c)||jsonb_build_object('asset',to_jsonb(a),'asset_restriction',to_jsonb(ar),'source_use',to_jsonb(cu),'release_ready',tongs.reference_visual_candidate_release_ready(c.id))order by c.created_at)from tongs.reference_visual_candidate_revisions c left join tongs.assets a on a.id=c.asset_id left join tongs.reference_visual_asset_restriction_sequences ars on ars.asset_id=c.asset_id left join tongs.reference_visual_asset_restriction_revisions ar on ar.id=ars.current_restriction_revision_id left join tongs.reference_visual_source_use_revisions cu on cu.id=c.source_use_revision_id where c.workspace_id=m.workspace_id and c.workpiece_id=m.workpiece_id and c.opportunity_id=m.opportunity_id),'[]'::jsonb),'selection',to_jsonb(sel),'release_ready',sel.id is not null and tongs.reference_visual_candidate_release_ready(sel.candidate_revision_id))order by m.ordinal)from tongs.reference_visual_plan_membership m join tongs.reference_visual_opportunity_revisions o on o.id=m.opportunity_revision_id left join tongs.source_revisions sr on sr.id=o.source_revision_id left join tongs.workpiece_source_link_revisions sl on sl.id=o.workpiece_source_link_revision_id left join tongs.reference_visual_source_use_sequences sus on sus.workspace_id=m.workspace_id and sus.workpiece_id=m.workpiece_id and sus.opportunity_id=m.opportunity_id left join tongs.reference_visual_source_use_revisions su on su.id=sus.current_use_revision_id left join tongs.reference_visual_recipe_sequences rs on rs.workspace_id=m.workspace_id and rs.workpiece_id=m.workpiece_id and rs.opportunity_id=m.opportunity_id left join tongs.reference_visual_recipe_revisions rr on rr.id=rs.current_recipe_revision_id left join tongs.reference_visual_rights_declaration_sequences rds on rds.workspace_id=m.workspace_id and rds.workpiece_id=m.workpiece_id and rds.opportunity_id=m.opportunity_id left join tongs.reference_visual_rights_declaration_revisions rd on rd.id=rds.current_declaration_revision_id left join lateral(select x.* from tongs.reference_visual_selections x where x.workspace_id=m.workspace_id and x.workpiece_id=m.workpiece_id and x.opportunity_id=m.opportunity_id and x.plan_revision_id=m.plan_revision_id order by x.revision desc limit 1)sel on true where m.plan_revision_id=p.id),'[]'::jsonb))end from tongs.reference_visual_plan_sequences s join tongs.reference_visual_plan_revisions p on p.id=s.current_plan_revision_id where s.workspace_id=p_workspace_id and s.workpiece_id=p_workpiece_id
$$;
create or replace function tongs.read_reference_visual_visual_package(p_workspace_id uuid,p_workpiece_id uuid)returns jsonb language sql stable security definer set search_path=pg_catalog,tongs as $$
 select case when not tongs.has_workspace_role(p_workspace_id,'viewer')then null else jsonb_build_object('visuals',coalesce((select jsonb_agg(jsonb_build_object('plan_revision_id',p.id,'plan_revision',p.revision,'opportunity_id',o.opportunity_id,'opportunity_revision_id',o.id,'opportunity_revision',o.revision,'candidate_revision_id',c.id,'candidate_revision',c.revision,'candidate_kind',c.candidate_kind,'asset_id',a.id,'asset_path',a.path,'storage_bucket',a.storage_bucket,'storage_key',a.storage_key,'mime_type',a.mime_type,'asset_content_hash',a.content_hash,'placement_hint',o.placement_hint,'duration_target_ms',o.duration_target_ms,'script_anchor',o.citation_anchor_json,'source_revision_id',o.source_revision_id,'source_revision',o.source_revision,'source_link_revision_id',o.workpiece_source_link_revision_id,'source_link_revision',o.workpiece_source_link_revision,'source_use',to_jsonb(u),'rights',to_jsonb(rd),'evidence',coalesce((select jsonb_agg(to_jsonb(ev))from unnest(r.evidence_revision_ids)e(id)join tongs.reference_visual_evidence_revisions ev on ev.id=e.id),'[]'::jsonb),'recipe',to_jsonb(r),'render_provenance',c.provenance_json)order by m.ordinal)from tongs.reference_visual_plan_sequences ps join tongs.reference_visual_plan_revisions p on p.id=ps.current_plan_revision_id join tongs.reference_visual_plan_membership m on m.plan_revision_id=p.id join tongs.reference_visual_opportunity_revisions o on o.id=m.opportunity_revision_id join lateral(select s.* from tongs.reference_visual_selections s where s.plan_revision_id=p.id and s.opportunity_id=o.opportunity_id order by s.revision desc limit 1)sel on true join tongs.reference_visual_candidate_revisions c on c.id=sel.candidate_revision_id left join tongs.assets a on a.id=c.asset_id left join tongs.reference_visual_recipe_revisions r on r.id=c.recipe_revision_id left join tongs.reference_visual_source_use_revisions u on u.id=c.source_use_revision_id left join tongs.reference_visual_rights_declaration_revisions rd on rd.id=c.rights_declaration_revision_id where ps.workspace_id=p_workspace_id and ps.workpiece_id=p_workpiece_id and tongs.reference_visual_candidate_release_ready(c.id)),'[]'::jsonb))end
$$;

alter table tongs.reference_visual_source_use_revisions enable row level security;alter table tongs.reference_visual_source_use_sequences enable row level security;
create trigger reference_visual_source_use_revisions_immutable before update or delete on tongs.reference_visual_source_use_revisions for each row execute function tongs.reject_reference_visual_immutable_mutation();
create policy reference_visual_source_use_revisions_viewer on tongs.reference_visual_source_use_revisions for select to authenticated using(tongs.has_workspace_role(workspace_id,'viewer'));create policy reference_visual_source_use_sequences_viewer on tongs.reference_visual_source_use_sequences for select to authenticated using(tongs.has_workspace_role(workspace_id,'viewer'));
revoke all on tongs.reference_visual_source_use_revisions,tongs.reference_visual_source_use_sequences from public,anon,authenticated;grant select on tongs.reference_visual_source_use_revisions,tongs.reference_visual_source_use_sequences to authenticated;
revoke all on function tongs.commit_reference_visual_source_use(uuid,uuid,uuid,uuid,bigint,uuid,uuid,uuid,text,boolean,text,jsonb,text,text,uuid),tongs.begin_reference_visual_render_v2(uuid,uuid,uuid,uuid,uuid,uuid,text,text,text,text,uuid)from public,anon,authenticated;grant execute on function tongs.commit_reference_visual_source_use(uuid,uuid,uuid,uuid,bigint,uuid,uuid,uuid,text,boolean,text,jsonb,text,text,uuid),tongs.begin_reference_visual_render_v2(uuid,uuid,uuid,uuid,uuid,uuid,text,text,text,text,uuid),tongs.read_current_reference_visual_plan(uuid,uuid),tongs.read_reference_visual_visual_package(uuid,uuid),tongs.reference_visual_candidate_release_ready(uuid)to authenticated,service_role;
revoke all on function tongs.reject_unready_reference_visual_selection()from public,anon;
comment on table tongs.reference_visual_source_use_revisions is 'Immutable creator-confirmed classification of factual evidence use versus reproduction of third-party material.';
